import { MeshStandardNodeMaterial, PlaneGeometry, Group, Mesh, EdgesGeometry, LineSegments, LineBasicMaterial, Color, DoubleSide, AmbientLight, DirectionalLight } from 'three/webgpu';
import { uv, texture, positionLocal, normalLocal, float, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };
  const accent = new THREE.Color(colors.accent);

  const group = new THREE.Group();
  group.name = 'hub-features-stat-tile';

  const W = 2.0, H = 1.25;
  const planeGeo = new THREE.PlaneGeometry(W, H, 64, 64);
  const cardMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    roughness: 0.55,
    metalness: 0.42,
    clearcoat: 0.2,
    clearcoatRoughness: 0.55,
    side: THREE.DoubleSide,
  });

  const baseY = float(0);
  cardMat.positionNode = positionLocal.add(normalLocal.mul(baseY));
  group.userData._baseY = baseY;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    cardMat.map = tex;
    cardMat.colorNode = texture(tex, uv());
    cardMat.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
    const depthNode = texture(depthTex, uv());
    const dispScale = float(0.12);
    group.userData._dispScale = dispScale;
    cardMat.positionNode = positionLocal.add(normalLocal.mul(depthNode.r.sub(0.5).mul(dispScale)));
    cardMat.needsUpdate = true;
  });

  const card = new THREE.Mesh(planeGeo, cardMat);
  group.add(card);

  // Accent edge frame — visible on hover/focus
  const edges = new THREE.EdgesGeometry(planeGeo);
  const edgeMat = new LineBasicMaterial({ color: accent, transparent: true, opacity: 0.0 });
  const edgeLines = new THREE.LineSegments(edges, edgeMat);
  edgeLines.position.z = 0.02;
  group.add(edgeLines);

  // Local rim light carrying accent hue
  const rimLight = new THREE.DirectionalLight(accent, 1.1);
  rimLight.position.set(1.3, 0.6, 1.5);
  group.add(rimLight);

  // Apply cinematic primitives
  const primResults = [];
  for (const prim of config.cinematicPrimitives ?? []) {
    const r = ctx.primitives[prim.name]?.(group, prim.params ?? {});
    if (r) primResults.push(r);
  }

  // Hover/press timelines
  let tlHover = null;
  let tlPress = null;
  let focused = false;
  const restState = { y: 0, scale: 1 };

  function onMouseEnter() {
    tlHover && tlHover.kill();
    tlHover = gsap.to(group.position, { y: group.userData.basePosY + 0.15, duration: 0.6, ease: 'power3.out', overwrite: true });
    gsap.to(edgeMat, { opacity: focused ? 1.0 : 0.55, duration: 0.3, ease: 'power2.out' });
  }
  function onMouseLeave() {
    tlHover && tlHover.kill();
    tlHover = gsap.to(group.position, { y: group.userData.basePosY, duration: 0.55, ease: 'power3.out', overwrite: true });
    gsap.to(edgeMat, { opacity: focused ? 1.0 : 0.0, duration: 0.3, ease: 'power2.out' });
  }
  function onPointerDown() {
    tlPress && tlPress.kill();
    tlPress = gsap.to(group.scale, { set: () => group.scale.set, value: 0.97, duration: 0.12, ease: 'back.out(2)', overwrite: true,
      onComplete: () => gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power4.out' }) });
  }
  function onClick() {
    ctx.emit('hub-features.select', { node: config.id ?? 'hub-features-stat-tile' });
  }
  function onFocus() {
    focused = true;
    gsap.to(edgeMat, { opacity: 1.0, duration: 0.4, ease: 'power2.out' });
  }
  function onBlur() {
    focused = false;
    gsap.to(edgeMat, { opacity: 0.0, duration: 0.4, ease: 'power2.out' });
  }

  group.userData.handlers = {
    'pointerenter': onMouseEnter,
    'pointerleave': onMouseLeave,
    pointerdown: onPointerDown,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  group.userData.basePosY = 0;
  // initial entry settle
  gsap.from(group.position, { y: 0.4, duration: 0.7, ease: 'power3.out', delay: 0.2 });
  gsap.from(group.scale, { x: 0.95, y: 0.95, z: 0.95, duration: 0.9, ease: 'power4.out', delay: 0.2, overwrite: true });

  group.userData.cleanup = () => {
    tlHover && tlHover.kill();
    tlPress && tlPress.kill();
    for (const r of primResults) r.cleanup && r.cleanup();
    cardMat.dispose && cardMat.dispose();
    planeGeo.dispose();
    edges.dispose();
    edgeMat.dispose();
    if (rimLight.dispose) rimLight.dispose();
  };

  return group;
}
